"const fs = require('fs');

function recover() {
    const raw = fs.readFileSync('match_0.json', 'utf8');
    const data = JSON.parse(raw);

    if (!data.content) {
        console.error('No content in Match 0!');
        return;
    }

    console.log('Content length:', data.content.length);

    // Split the content into lines
    const lines = data.content.split('\n');
    let outputLines = [];

    for (const line of lines) {
        // Look for line prefixes like "  23: const foo = ..." or "123: const bar = ..."
        // Note: the system formats it as "<line_number>: <original_line>" or similar
        const match = line.match(/^\s*(\d+):\s(.*)$/);
        if (match) {
            outputLines.push(match[2]);
        }
    }

    console.log('Processed lines count:', outputLines.length);
    if (outputLines.length > 0) {
        const fileContent = outputLines.join('\n');
        fs.writeFileSync('frontend/src/components/ProductWizard.jsx', fileContent);
        console.log('Successfully recovered original ProductWizard.jsx from Step 272 log content!');
    } else {
        console.log('Could not parse lines. Content preview:', data.content.substring(0, 1000));
    }
}

recover();
"
